import torch,json
for L,seeds,name in [(1,[986,6714,3841,5907,5323],'code_l1'),(0,[4640,7086,3819],'code_l0')]:
    w1=W(f'model.layers.{L}.feed_forward.w1.weight'); w3=W(f'model.layers.{L}.feed_forward.w3.weight'); w2=W(f'model.layers.{L}.feed_forward.w2.weight').T
    def nz(x): return x/x.norm(dim=1,keepdim=True)
